L["Crit flourish"] = "Effetto critico"
L["Critical hits only: the number jumps much further, flashes gold, and a star bursts behind its icon."] = "Solo colpi critici: il numero salta molto di più, brilla d'oro e una stella esplode dietro la sua icona."
L["Killing blow mark"] = "Segno del colpo di grazia"
L["A skull on the row whose attack killed the enemy, with a count once it has killed more than one."] = "Un teschio sulla riga il cui attacco ha ucciso il nemico, con un conteggio quando ne ha uccisi più di uno."
L["Splash side"] = "Lato degli schizzi"
L["Which side of the number a hit floats off."] = "Da quale lato del numero vola via un colpo."
L["Effects"] = "Effetti"
